#!/usr/bin/env bash
set -euo pipefail

# update-shas.sh has already generated packaging/ from the published release.
: "${GH_TOKEN:?Set RELEASE_BOT_TOKEN with Contents and Pull requests write permissions}"
: "${RELEASE_TAG:?A stable release tag is required}"
if [[ ! "$RELEASE_TAG" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
  echo '::error::Manifest sync requires a stable vX.Y.Z release tag'
  exit 1
fi

if git diff --quiet -- packaging/; then
  echo '::notice::Packaging manifests already match the release'
  exit 0
fi

branch="release/${RELEASE_TAG}-manifests"
# Capture the remote head before replacing our generated branch. A concurrent
# writer must cause a failure, not lose their changes to an unconditional force.
expected="$(git ls-remote --heads origin "refs/heads/$branch" | cut -f1)"
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
git add -- packaging/
git commit -m "chore(release): sync manifests to $RELEASE_TAG"
git push --force-with-lease="refs/heads/$branch:$expected" origin "HEAD:refs/heads/$branch"

pr_number="$(gh pr list --base main --head "$branch" --state open --json number --jq '.[0].number // empty')"
if [ -z "$pr_number" ]; then
  body_file="$(mktemp)"
  trap 'rm -f "$body_file"' EXIT
  printf 'Sync distribution manifests to %s using the published release checksums.\n\nGenerated by the release workflow. Required CI must pass before merging.\n' "$RELEASE_TAG" > "$body_file"
  gh pr create --base main --head "$branch" \
    --title "chore(release): sync manifests to $RELEASE_TAG" --body-file "$body_file"
  pr_number="$(gh pr list --base main --head "$branch" --state open --json number --jq '.[0].number // empty')"
fi
if [ -z "$pr_number" ]; then
  echo '::error::Could not resolve the manifest PR after creation'
  exit 1
fi
gh pr merge "$pr_number" --auto --squash
echo "::notice::Manifest PR #$pr_number is awaiting required checks and merge"
